from collections import deque

def level_order(tree):
    if tree is None:
        return []

    queue = deque([tree])
    out = []

    while queue:
        # BFS processes the oldest discovered node first.
        node = {{take_front}}
        value, left, right = node
        out.append(value)

        if left is not None:
            # Newly discovered children join the back of the queue.
            {{add_left}}
        if right is not None:
            {{add_right}}

    return out

